import {requireVendorMember} from '@/lib/vendors';
import {prisma} from '@/lib/prisma';
export const dynamic='force-dynamic';
export default async function VendorEarnings({searchParams}:{searchParams:Promise<{vendorId?:string}>}){const p=await searchParams;const {vendor}=await requireVendorMember(p.vendorId);const [entries,earnings]=await Promise.all([prisma.vendorLedgerEntry.findMany({where:{vendorId:vendor.id},orderBy:{createdAt:'desc'},take:50}),prisma.vendorEarning.aggregate({where:{vendorId:vendor.id},_sum:{grossMmk:true,platformCommissionMmk:true,netMmk:true}})]);return <main className="admin-content"><p className="eyebrow">VENDOR FINANCE</p><h1 className="admin-title">Earnings</h1><div className="admin-stat-grid mt-8"><Stat label="Gross sales" value={earnings._sum.grossMmk||0}/><Stat label="Commission" value={earnings._sum.platformCommissionMmk||0}/><Stat label="Net earnings" value={earnings._sum.netMmk||0}/></div><div className="admin-panel mt-8 overflow-x-auto"><table className="admin-table"><thead><tr><th>Event</th><th>Amount</th><th>Source</th><th>Date</th></tr></thead><tbody>{entries.map(e=><tr key={e.id}><td>{e.eventType}</td><td>{e.amountMmk.toLocaleString()} MMK</td><td>{e.sourceType}</td><td>{e.createdAt.toLocaleDateString()}</td></tr>)}</tbody></table>{!entries.length&&<p className="admin-empty">No ledger entries yet. Verified vendor sales will appear here after commission integration is enabled.</p>}</div></main>}
function Stat({label,value}:{label:string;value:number}){return <div className="admin-stat"><p className="text-2xl font-bold">{value.toLocaleString()} MMK</p><p className="mt-1 text-xs text-slate-500">{label}</p></div>}
